  }
}

resource "aws_kms_alias" "this" {
  for_each      = toset(local.kms_usages)
  name          = "alias/${local.p}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

arguments.content:
# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.p}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = { Name = "${local.p}-db-subnets" }
}

resource "aws_db_instance" "main" {
  identifier             = "${local.p}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  port                   = 5432
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags                   = { Name = "${local.p}-postgres" }

  lifecycle {
    ignore_changes = [engine_version]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "projections" {
  name         = "${local.p}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = { Name = "${local.p}-projections" }
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.p}-cache-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = { Name = "${local.p}-cache-subnets" }
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id       = "${local.p}-valkey"
  description                = "ClearLedger projection cache"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  automatic_failover_enabled = false
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  apply_immediately          = true
  tags                       = { Name = "${local.p}-valkey" }
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.p}-ledger-audit-${local.account_id}"
  force_destroy = true
  tags          = { Name = "${local.p}-ledger-audit" }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue + DLQ
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.p}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = { Name = "${local.p}-events-dlq" }
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.p}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = { Name = "${local.p}-events" }
}

locals {
  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }

  log_group_arns = {
    for k, name in local.log_groups : k => [
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}",
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}:*",
    ]
  }

  all_kms_arns = [for k in local.kms_usages : local.kms_arn[k]]

  queue_arns  = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn]
  table_arns  = [aws_dynamodb_table.projections.arn, "${aws_dynamodb_table.projections.arn}/index/AccountIndex"]
  bucket_arns = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]

  sqs_all_actions    = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_all_actions    = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_all_actions     = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  log_write_actions  = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  log_deny_actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
  kms_use_actions    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny_actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
  kms_guard_statement = {
    Sid      = "DenyKmsKeyDestruction"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms_arns
  }

  other_logs = {
    for k in keys(local.log_groups) : k => flatten([
      for o, arns in local.log_group_arns : arns if o != k
    ])
  }
  all_log_arns = flatten(values(local.log_group_arns))

  role_trust = {
    ecs_execution = "ecs-tasks.amazonaws.com"
    ecs_task      = "ecs-tasks.amazonaws.com"
    projector     = "lambda.amazonaws.com"
    relay         = "lambda.amazonaws.com"
    archiver      = "lambda.amazonaws.com"
    scheduler     = "scheduler.amazonaws.com"
  }

  role_names = {
    ecs_execution = "${local.p}-ecs-execution"
    ecs_task      = "${local.p}-ecs-task"
    projector     = "${local.p}-projector"
    relay         = "${local.p}-outbox-relay"
    archiver      = "${local.p}-audit-archiver"
    scheduler     = "${local.p}-scheduler"
  }

  role_policies = {
    ecs_execution = [
      {
        Sid      = "ApiLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_group_arns["api"]
      },
      local.kms_guard_statement,
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = local.queue_arns },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = local.table_arns },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.bucket_arns },
      { Sid = "DenyKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = local.all_kms_arns },
      { Sid = "DenyForeignLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs["api"] },
    ]

    ecs_task = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = local.table_arns
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      {
        Sid      = "ApiLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_group_arns["api"]
      },
      local.kms_guard_statement,
      { Sid = "DenyConsumeMainQueue", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
      { Sid = "DenyDlq", Effect = "Deny", Action = local.sqs_all_actions, Resource = [aws_sqs_queue.dlq.arn] },
      { Sid = "DenyDynamoDbMutation", Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_arns },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.bucket_arns },
      { Sid = "DenyForeignKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = [local.kms_arn["database"], local.kms_arn["audit"]] },
      { Sid = "DenyForeignLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs["api"] },
    ]

    projector = [
      {
        Sid      = "ConsumeMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "ForwardToDlq"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [aws_sqs_queue.dlq.arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = local.table_arns
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      {
        Sid      = "ProjectorLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_group_arns["projector"]
      },
      local.kms_guard_statement,
      { Sid = "DenyPublishMainQueue", Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.main.arn] },
      { Sid = "DenyConsumeDlq", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.dlq.arn] },
      { Sid = "DenyDynamoDbDelete", Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_arns },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.bucket_arns },
      { Sid = "DenyForeignKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = [local.kms_arn["database"], local.kms_arn["audit"]] },
      { Sid = "DenyForeignLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs["projector"] },
    ]

    relay = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "UseMessagingAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["messaging"], local.kms_arn["database"]]
      },
      {
        Sid      = "RelayLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_group_arns["relay"]
      },
      local.kms_guard_statement,
      { Sid = "DenyConsumeMainQueue", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
      { Sid = "DenyDlq", Effect = "Deny", Action = local.sqs_all_actions, Resource = [aws_sqs_queue.dlq.arn] },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = local.table_arns },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.bucket_arns },
      { Sid = "DenyForeignKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = [local.kms_arn["projection"], local.kms_arn["audit"]] },
      { Sid = "DenyForeignLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs["relay"] },
    ]

    archiver = [
      {
        Sid      = "AppendAuditObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource = ["${aws_s3_bucket.audit.arn}/ledger-audit/*"]
      },
      {
        Sid      = "AuditBucketMetadata"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [aws_s3_bucket.audit.arn]
      },
      {
        Sid      = "UseAuditAndDatabaseKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["audit"], local.kms_arn["database"]]
      },
      {
        Sid      = "ArchiverLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_group_arns["archiver"]
      },
      local.kms_guard_statement,
      { Sid = "DenyAuditDeletion", Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.bucket_arns },
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = local.queue_arns },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = local.table_arns },
      { Sid = "DenyForeignKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]] },
      { Sid = "DenyForeignLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs["archiver"] },
    ]

    scheduler = [
      {
        Sid      = "InvokeScheduledWorkers"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = [aws_lambda_function.relay.arn, aws_lambda_function.archiver.arn]
      },
      local.kms_guard_statement,
      { Sid = "DenyInvokeProjector", Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.projector.arn] },
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = local.queue_arns },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = local.table_arns },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.bucket_arns },
      { Sid = "DenyKmsUse", Effect = "Deny", Action = local.kms_deny_actions, Resource = local.all_kms_arns },
      { Sid = "DenyLogs", Effect = "Deny", Action = local.log_deny_actions, Resource = local.all_log_arns },
    ]
  }
}

resource "aws_iam_role" "this" {
  for_each = local.role_trust
  name     = local.role_names[each.key]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = each.value }
    }]
  })

  force_detach_policies = true

  tags = {
    Name            = local.role_names[each.key]
    ClearLedgerRole = each.key
  }
}

resource "aws_iam_role_policy" "this" {
  for_each = local.role_trust
  name     = "${local.role_names[each.key]}-policy"
  role     = aws_iam_role.this[each.key].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.role_policies[each.key]
  })
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "api" {
  name               = "${local.p}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
  tags               = { Name = "${local.p}-alb" }
}

resource "aws_lb_target_group" "api" {
  name        = "${local.p}-api-tg"
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    matcher             = "200"
    port                = "traffic-port"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = { Name = "${local.p}-api-tg" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = { Name = "${local.p}-http" }
}

# ---------------------------------------------------------------------------
# ECS Fargate API service
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "${local.p}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = { Name = "${local.p}-cluster" }
}

locals {
  common_worker_env = {
    AWS_REGION            = var.region
    AWS_DEFAULT_REGION    = var.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = var.container_aws_endpoint_url
  }

  api_env = merge(local.common_worker_env, {
    PORT                 = "8080"
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CACHE_TTL_SECONDS    = "90"
    AUTH_ISSUER          = local.issuer_url
    AUTH_AUDIENCES       = join(",", [aws_cognito_user_pool_client.read.id, aws_cognito_user_pool_client.write.id, aws_cognito_user_pool_client.admin.id])
    AUTH_JWKS_URL        = local.jwks_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["api"].name
  })
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.p}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.this["ecs_execution"].arn
  task_role_arn            = aws_iam_role.this["ecs_task"].arn

  container_definitions = jsonencode([
    {
      name      = "api"
      image     = var.api_image
      essential = true
      portMappings = [{
        containerPort = 8080
        hostPort      = 8080
        protocol      = "tcp"
      }]
      environment = [for k in sort(keys(local.api_env)) : { name = k, value = local.api_env[k] }]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.this["api"].name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])

  tags = { Name = "${local.p}-api" }
}

resource "aws_ecs_service" "api" {
  name            = "${local.p}-api"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  launch_type     = "FARGATE"
  desired_count   = 2

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  wait_for_steady_state = false

  depends_on = [aws_lb_listener.http, aws_iam_role_policy.this]

  tags = { Name = "${local.p}-api" }
}

# ---------------------------------------------------------------------------
# Lambda workers
# ---------------------------------------------------------------------------
resource "aws_lambda_function" "projector" {
  function_name = "${local.p}-projector"
  package_type  = "Image"
  image_uri     = var.projector_image
  role          = aws_iam_role.this["projector"].arn
  timeout       = 30
  memory_size   = 256

  environment {
    variables = merge(local.common_worker_env, {
      PROJECTION_TABLE     = aws_dynamodb_table.projections.name
      VALKEY_URL           = local.valkey_url
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  depends_on = [aws_iam_role_policy.this]
  tags       = { Name = "${local.p}-projector" }
}

resource "aws_lambda_function" "relay" {
  function_name = "${local.p}-outbox-relay"
  package_type  = "Image"
  image_uri     = var.relay_image
  role          = aws_iam_role.this["relay"].arn
  timeout       = 60
  memory_size   = 256

  environment {
    variables = merge(local.common_worker_env, {
      DATABASE_URL         = local.database_url
      SQS_QUEUE_URL        = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE    = "50"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  depends_on = [aws_iam_role_policy.this]
  tags       = { Name = "${local.p}-outbox-relay" }
}

resource "aws_lambda_function" "archiver" {
  function_name = "${local.p}-audit-archiver"
  package_type  = "Image"
  image_uri     = var.archiver_image
  role          = aws_iam_role.this["archiver"].arn
  timeout       = 60
  memory_size   = 256

  environment {
    variables = merge(local.common_worker_env, {
      DATABASE_URL         = local.database_url
      AUDIT_BUCKET         = aws_s3_bucket.audit.id
      AUDIT_PREFIX         = "ledger-audit/"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  depends_on = [aws_iam_role_policy.this]
  tags       = { Name = "${local.p}-audit-archiver" }
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]
}

# ---------------------------------------------------------------------------
# EventBridge Scheduler
# ---------------------------------------------------------------------------
resource "aws_scheduler_schedule" "outbox" {
  name                = "${local.p}-outbox-relay"
  state               = "ENABLED"
  schedule_expression = "rate(1 minute)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "outbox-relay" })
  }
}

resource "aws_scheduler_schedule" "archive" {
  name                = "${local.p}-audit-archiver"
  state               = "ENABLED"
  schedule_expression = "rate(5 minutes)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "clearledger.scheduler", job = "audit-archiver" })
  }
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.p}-users"
  tags = { Name = "${local.p}-users" }
}

resource "aws_cognito_resource_server" "clearledger" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.p}-clearledger"

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }
  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }
  scope {
    scope_name        = "admin"
    scope_description = "Administrative projection rebuilds"
  }
}

locals {
  cognito_clients = {
    read  = "clearledger/read"
    write = "clearledger/write"
    admin = "clearledger/admin"
  }
}

resource "aws_cognito_user_pool_client" "read" {
  name                                 = "${local.p}-read"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/read"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]
  depends_on                           = [aws_cognito_resource_server.clearledger]
}

resource "aws_cognito_user_pool_client" "write" {
  name                                 = "${local.p}-write"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/write"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]
  depends_on                           = [aws_cognito_resource_server.clearledger]
}

resource "aws_cognito_user_pool_client" "admin" {
  name                                 = "${local.p}-admin"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/admin"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]
  depends_on                           = [aws_cognito_resource_server.clearledger]
}

