#!/usr/bin/env python3
"""ClearLedger operational helper: drift repair and data-plane convergence."""
import datetime
import hashlib
import json
import os
import re
import sys
import time

import boto3
from botocore.config import Config

PREFIX = os.environ["CL_PREFIX"]
REGION = os.environ.get("CL_REGION", "us-east-1")
ENDPOINT = os.environ["CL_ENDPOINT"]
INFRA_DIR = os.environ.get("CL_INFRA_DIR", "/workspace/submission/infra")

BOTO_CFG = Config(retries={"max_attempts": 8, "mode": "standard"}, connect_timeout=10, read_timeout=60)


def log(msg):
    print(f"[ops {datetime.datetime.utcnow():%H:%M:%S}] {msg}", file=sys.stderr, flush=True)


def client(name):
    return boto3.client(
        name,
        endpoint_url=ENDPOINT,
        region_name=REGION,
        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID", "test"),
        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY", "test"),
        config=BOTO_CFG,
    )


def outputs():
    path = os.environ.get("CL_OUTPUTS")
    if not path or not os.path.exists(path):
        return {}
    raw = json.load(open(path))
    return {k: v.get("value") for k, v in raw.items()}


def manifest():
    return json.load(open(os.environ["CL_MANIFEST"]))


def tfstate_resources():
    path = os.path.join(INFRA_DIR, "terraform.tfstate")
    if not os.path.exists(path):
        return []
    try:
        st = json.load(open(path))
    except Exception:
        return []
    return st.get("resources", [])


# ---------------------------------------------------------------------------
# pre-apply: KMS key repair
# ---------------------------------------------------------------------------
def preapply():
    kms = client("kms")
    key_ids = set()
    for res in tfstate_resources():
        if res.get("type") == "aws_kms_key" and res.get("mode") == "managed":
            for inst in res.get("instances", []):
                kid = inst.get("attributes", {}).get("key_id") or inst.get("attributes", {}).get("id")
                if kid:
                    key_ids.add(kid)
    try:
        for page in kms.get_paginator("list_aliases").paginate():
            for a in page.get("Aliases", []):
                if a.get("AliasName", "").startswith(f"alias/{PREFIX}-") and a.get("TargetKeyId"):
                    key_ids.add(a["TargetKeyId"])
    except Exception as e:  # noqa
        log(f"list_aliases failed: {e}")
    for kid in sorted(key_ids):
        try:
            meta = kms.describe_key(KeyId=kid)["KeyMetadata"]
        except Exception as e:
            log(f"describe_key {kid}: {e}")
            continue
        state = meta.get("KeyState")
        if state == "PendingDeletion":
            log(f"cancelling scheduled deletion of KMS key {kid}")
            kms.cancel_key_deletion(KeyId=kid)
            state = kms.describe_key(KeyId=kid)["KeyMetadata"].get("KeyState")
        if state == "Disabled":
            log(f"re-enabling KMS key {kid}")
            kms.enable_key(KeyId=kid)
        try:
            if not kms.get_key_rotation_status(KeyId=kid).get("KeyRotationEnabled"):
                kms.enable_key_rotation(KeyId=kid)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# post-apply: IAM + security group drift
# ---------------------------------------------------------------------------
def delete_managed_policy(iam, arn):
    try:
        for v in iam.list_policy_versions(PolicyArn=arn).get("Versions", []):
            if not v.get("IsDefaultVersion"):
                iam.delete_policy_version(PolicyArn=arn, VersionId=v["VersionId"])
    except Exception as e:
        log(f"list/delete policy versions {arn}: {e}")
    iam.delete_policy(PolicyArn=arn)


def repair_iam():
    out = outputs()
    iam = client("iam")
    role_names = out.get("role_names") or {}
    canonical = out.get("role_policy_names") or {}
    for key, role in role_names.items():
        keep = canonical.get(key)
        try:
            names = []
            for page in iam.get_paginator("list_role_policies").paginate(RoleName=role):
                names.extend(page.get("PolicyNames", []))
            for n in names:
                if n != keep:
                    log(f"removing out-of-band inline policy {n} from {role}")
                    iam.delete_role_policy(RoleName=role, PolicyName=n)
            attached = []
            for page in iam.get_paginator("list_attached_role_policies").paginate(RoleName=role):
                attached.extend(page.get("AttachedPolicies", []))
            for p in attached:
                log(f"detaching out-of-band managed policy {p['PolicyArn']} from {role}")
                iam.detach_role_policy(RoleName=role, PolicyArn=p["PolicyArn"])
            r = iam.get_role(RoleName=role)["Role"]
            if r.get("PermissionsBoundary"):
                log(f"removing out-of-band permissions boundary from {role}")
                iam.delete_role_permissions_boundary(RoleName=role)
        except iam.exceptions.NoSuchEntityException:
            log(f"role {role} missing (terraform should have recreated it)")
    # prefixed customer-managed policies that are not attached anywhere
    try:
        pols = []
        for page in iam.get_paginator("list_policies").paginate(Scope="Local"):
            pols.extend(page.get("Policies", []))
    except Exception as e:
        log(f"list_policies failed: {e}")
        pols = []
    for p in pols:
        if not p.get("PolicyName", "").startswith(PREFIX):
            continue
        arn = p["Arn"]
        try:
            ents = iam.list_entities_for_policy(PolicyArn=arn)
            attached = ents.get("PolicyRoles", []) + ents.get("PolicyUsers", []) + ents.get("PolicyGroups", [])
            ours = set(role_names.values())
            for r in ents.get("PolicyRoles", []):
                if r["RoleName"] in ours:
                    iam.detach_role_policy(RoleName=r["RoleName"], PolicyArn=arn)
                    attached = [a for a in attached if a.get("RoleName") != r["RoleName"]]
            if not attached:
                log(f"deleting unattached prefixed policy {arn}")
                delete_managed_policy(iam, arn)
        except Exception as e:
            log(f"policy cleanup {arn}: {e}")


PUBLIC = ("0.0.0.0/0", "::/0")


def _strip(perm, keep_fn):
    """Return a revoke-able permission containing only ranges selected by keep_fn."""
    p = {k: perm[k] for k in ("IpProtocol", "FromPort", "ToPort") if k in perm}
    v4 = [r for r in perm.get("IpRanges", []) if keep_fn(r.get("CidrIp"))]
    v6 = [r for r in perm.get("Ipv6Ranges", []) if keep_fn(r.get("CidrIpv6"))]
    if not v4 and not v6:
        return None
    if v4:
        p["IpRanges"] = [{"CidrIp": r["CidrIp"]} for r in v4]
    if v6:
        p["Ipv6Ranges"] = [{"CidrIpv6": r["CidrIpv6"]} for r in v6]
    return p


def repair_security_groups():
    m = manifest()
    sgs = m["network"]["security_group_ids"]
    ec2 = client("ec2")
    for role, sg in sgs.items():
        try:
            g = ec2.describe_security_groups(GroupIds=[sg])["SecurityGroups"][0]
        except Exception as e:
            log(f"describe sg {sg}: {e}")
            continue
        if role in ("ecs", "rds", "valkey"):
            for perm in g.get("IpPermissions", []):
                if role == "ecs":
                    bad = _strip(perm, lambda c: c is not None)  # ecs ingress: SG-sourced only
                else:
                    bad = _strip(perm, lambda c: c in PUBLIC)
                if bad:
                    log(f"revoking out-of-band ingress on {role} sg {sg}: {bad}")
                    try:
                        ec2.revoke_security_group_ingress(GroupId=sg, IpPermissions=[bad])
                    except Exception as e:
                        log(f"revoke ingress failed: {e}")
        if role in ("rds", "valkey"):
            perms = g.get("IpPermissionsEgress", [])
            if perms:
                log(f"revoking out-of-band egress on {role} sg {sg}")
                for perm in perms:
                    clean = {k: v for k, v in perm.items() if k in (
                        "IpProtocol", "FromPort", "ToPort", "IpRanges", "Ipv6Ranges", "UserIdGroupPairs", "PrefixListIds")}
                    for k in ("IpRanges", "Ipv6Ranges", "UserIdGroupPairs", "PrefixListIds"):
                        if k in clean and not clean[k]:
                            del clean[k]
                    try:
                        ec2.revoke_security_group_egress(GroupId=sg, IpPermissions=[clean])
                    except Exception as e:
                        log(f"revoke egress failed: {e}")
        if role == "alb":
            for perm in g.get("IpPermissionsEgress", []):
                bad = _strip(perm, lambda c: c in PUBLIC)
                if bad:
                    log(f"revoking public egress on alb sg {sg}")
                    try:
                        ec2.revoke_security_group_egress(GroupId=sg, IpPermissions=[bad])
                    except Exception as e:
                        log(f"revoke egress failed: {e}")


def postapply():
    repair_iam()
    repair_security_groups()


# ---------------------------------------------------------------------------
# converge: data plane
# ---------------------------------------------------------------------------
ENV_ORDER = ["schemaVersion", "eventId", "eventType", "aggregateType", "aggregateId",
             "aggregateVersion", "occurredAt", "correlationId", "idempotencyKey", "data"]
DATA_ORDER = ["kind", "accountId", "reference", "debitParty", "creditParty",
              "entryId", "status", "clearingStage", "memo"]
BATCH_RE = re.compile(r"^ledger-audit/batch-(\d{8})-(\d{8})-([0-9a-f]{16})\.ndjson$")
UUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
AUDIT_PREFIX = "ledger-audit/"
AUDIT_BATCH = 100
CACHE_TTL = 90


def _ordered(obj, order):
    out = {}
    for k in order:
        if k in obj:
            out[k] = obj[k]
    for k in sorted(obj):
        if k not in out:
            out[k] = obj[k]
    return out


def canonical_envelope(payload):
    env = _ordered(payload, ENV_ORDER)
    if isinstance(env.get("data"), dict):
        env["data"] = _ordered(env["data"], DATA_ORDER)
    return json.dumps(env, separators=(",", ":"), ensure_ascii=False)


def _frac(dt):
    us = dt.microsecond
    if us == 0:
        return ""
    if us % 1000 == 0:
        return ".%03d" % (us // 1000)
    return ".%06d" % us


def ts_offset(dt):
    dt = dt.astimezone(datetime.timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + _frac(dt) + "+00:00"


def ts_z(dt):
    dt = dt.astimezone(datetime.timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + _frac(dt) + "Z"


def pg_connect():
    import psycopg2
    import psycopg2.extras  # noqa
    last = None
    for _ in range(30):
        try:
            conn = psycopg2.connect(
                host=os.environ["CL_DB_HOST"], port=int(os.environ["CL_DB_PORT"]),
                dbname=os.environ["CL_DB_NAME"], user=os.environ["CL_DB_USER"],
                password=os.environ["CL_DB_PASSWORD"], connect_timeout=10,
                application_name="clearledger-deploy")
            return conn
        except Exception as e:
            last = e
            time.sleep(2)
    raise last


def load_pg(conn):
    with conn.cursor() as cur:
        cur.execute("""
            SELECT settlement_id::text, account_id, reference, debit_party, credit_party,
                   current_status, current_stage, last_entry_id::text, last_memo, version,
                   entry_count, created_at, updated_at
              FROM clearledger.settlements""")
        cols = [d[0] for d in cur.description]
        settlements = {r[0]: dict(zip(cols, r)) for r in cur.fetchall()}
        cur.execute("""
            SELECT settlement_id::text, aggregate_version, event_id::text, event_type,
                   correlation_id, occurred_at, payload
              FROM clearledger.events ORDER BY settlement_id, aggregate_version""")
        cols = [d[0] for d in cur.description]
        events = [dict(zip(cols, r)) for r in cur.fetchall()]
    conn.commit()
    return settlements, events


def load_outbox(conn):
    with conn.cursor() as cur:
        cur.execute("""
            SELECT seq, event_id::text, payload, published_at, archived_at
              FROM clearledger.outbox ORDER BY seq""")
        cols = [d[0] for d in cur.description]
        rows = [dict(zip(cols, r)) for r in cur.fetchall()]
    conn.commit()
    return rows


# -- outbox relay ------------------------------------------------------------
def publish_outbox(conn, queue_url):
    sqs = client("sqs")
    total = 0
    while True:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT seq, payload FROM clearledger.outbox
                 WHERE published_at IS NULL ORDER BY seq LIMIT 50
                 FOR UPDATE SKIP LOCKED""")
            rows = cur.fetchall()
            if not rows:
                conn.commit()
                break
            for seq, payload in rows:
                sqs.send_message(QueueUrl=queue_url, MessageBody=canonical_envelope(payload))
                cur.execute("""
                    UPDATE clearledger.outbox
                       SET published_at = GREATEST(NOW(), created_at), attempts = attempts + 1, last_error = NULL
                     WHERE seq = %s AND published_at IS NULL""", (seq,))
                total += 1
        conn.commit()
    log(f"outbox: published {total} pending event(s)")
    return total


def wait_queue_drained(queue_url, esm_uuid, timeout=90):
    sqs = client("sqs")
    lam = client("lambda")
    try:
        st = lam.get_event_source_mapping(UUID=esm_uuid).get("State")
        if st not in ("Enabled", "Enabling", "Updating", "Creating"):
            log(f"event source mapping state {st}; enabling")
            lam.update_event_source_mapping(UUID=esm_uuid, Enabled=True)
    except Exception as e:
        log(f"esm check: {e}")
    deadline = time.time() + timeout
    zero_streak = 0
    while time.time() < deadline:
        a = sqs.get_queue_attributes(QueueUrl=queue_url, AttributeNames=[
            "ApproximateNumberOfMessages", "ApproximateNumberOfMessagesNotVisible",
            "ApproximateNumberOfMessagesDelayed"])["Attributes"]
        n = sum(int(a.get(k, 0)) for k in a)
        if n == 0:
            zero_streak += 1
            if zero_streak >= 2:
                log("main queue drained")
                return True
        else:
            zero_streak = 0
        time.sleep(1.5)
    log("main queue not fully drained before timeout; continuing")
    return False


# -- DynamoDB ---------------------------------------------------------------
def S(v):
    return {"S": str(v)}


def N(v):
    return {"N": str(int(v))}


def desired_dynamo(settlements, events):
    items = {}
    for sid, s in settlements.items():
        pk = f"SETTLEMENT#{sid}"
        it = {
            "PK": S(pk), "SK": S("STATE"),
            "GSI1PK": S(f"ACCOUNT#{s['account_id']}"), "GSI1SK": S(f"SETTLEMENT#{sid}"),
            "settlement_id": S(sid), "account_id": S(s["account_id"]), "reference": S(s["reference"]),
            "debit_party": S(s["debit_party"]), "credit_party": S(s["credit_party"]),
            "status": S(s["current_status"]), "clearing_stage": S(s["current_stage"]),
            "version": N(s["version"]), "entry_count": N(s["entry_count"]),
            "updated_at": S(ts_offset(s["updated_at"])),
        }
        if s["last_entry_id"] is not None:
            it["last_entry_id"] = S(s["last_entry_id"])
        if s["last_memo"] is not None:
            it["last_memo"] = S(s["last_memo"])
        items[(pk, "STATE")] = it
    for e in events:
        sid = e["settlement_id"]
        if sid not in settlements:
            continue
        pk = f"SETTLEMENT#{sid}"
        sk = "EVENT#%08d" % e["aggregate_version"]
        d = (e["payload"] or {}).get("data") or {}
        it = {
            "PK": S(pk), "SK": S(sk), "settlement_id": S(sid), "event_id": S(e["event_id"]),
            "version": N(e["aggregate_version"]), "event_type": S(e["event_type"]),
            "status": S(d.get("status")), "clearing_stage": S(d.get("clearingStage")),
            "occurred_at": S(ts_offset(e["occurred_at"])), "correlation_id": S(e["correlation_id"]),
            "envelope": S(canonical_envelope(e["payload"])),
        }
        if d.get("entryId") is not None:
            it["entry_id"] = S(d["entryId"])
        if d.get("memo") is not None:
            it["memo"] = S(d["memo"])
        items[(pk, sk)] = it
    return items


def scan_table(ddb, table):
    items = {}
    kw = {"TableName": table, "ConsistentRead": True}
    while True:
        r = ddb.scan(**kw)
        for it in r.get("Items", []):
            pk = it.get("PK", {}).get("S")
            sk = it.get("SK", {}).get("S")
            items[(pk, sk)] = it
        if not r.get("LastEvaluatedKey"):
            break
        kw["ExclusiveStartKey"] = r["LastEvaluatedKey"]
    return items


def _norm(item):
    return json.dumps(item, sort_keys=True)


def converge_dynamo(conn, table):
    ddb = client("dynamodb")
    existing = scan_table(ddb, table)          # scan first ...
    settlements, events = load_pg(conn)        # ... then read the system of record
    desired = desired_dynamo(settlements, events)
    puts = deletes = 0
    for key, it in desired.items():
        cur = existing.get(key)
        if cur is None or _norm(cur) != _norm(it):
            ddb.put_item(TableName=table, Item=it)
            puts += 1
    for key, cur in existing.items():
        if key in desired:
            continue
        pk, sk = key
        if pk is None or sk is None:
            continue
        ddb.delete_item(TableName=table, Key={"PK": cur["PK"], "SK": cur["SK"]})
        deletes += 1
    log(f"dynamodb: {puts} item(s) written, {deletes} stray item(s) deleted, "
        f"{len(desired)} desired item(s)")
    return puts + deletes, settlements


# -- Valkey -----------------------------------------------------------------
def projection_json(s):
    obj = {
        "settlementId": s["settlement_id"], "accountId": s["account_id"], "reference": s["reference"],
        "debitParty": s["debit_party"], "creditParty": s["credit_party"],
        "status": s["current_status"], "clearingStage": s["current_stage"],
    }
    if s["last_entry_id"] is not None:
        obj["lastEntryId"] = s["last_entry_id"]
    if s["last_memo"] is not None:
        obj["lastMemo"] = s["last_memo"]
    obj["version"] = int(s["version"])
    obj["entryCount"] = int(s["entry_count"])
    obj["updatedAt"] = ts_z(s["updated_at"])
    return json.dumps(obj, separators=(",", ":"), ensure_ascii=False)


def converge_valkey(conn, host, port):
    import redis
    settlements, _ = load_pg(conn)
    r = redis.Redis(host=host, port=int(port), socket_timeout=15, socket_connect_timeout=10)
    # purge every non-default logical database
    try:
        ks = r.info("keyspace") or {}
        for db in ks:
            idx = int(str(db).replace("db", ""))
            if idx != 0:
                rr = redis.Redis(host=host, port=int(port), db=idx, socket_timeout=15)
                rr.flushdb()
                log(f"valkey: flushed stray logical db {idx}")
    except Exception as e:
        log(f"valkey keyspace check: {e}")
    desired = {f"clearledger:settlement:{sid}": projection_json(s) for sid, s in settlements.items()}
    stray = []
    for k in r.scan_iter(match="*", count=1000):
        ks = k.decode("utf-8", "replace") if isinstance(k, bytes) else k
        if ks not in desired:
            stray.append(k)
    for i in range(0, len(stray), 500):
        r.delete(*stray[i:i + 500])
    pipe = r.pipeline(transaction=False)
    for k, v in desired.items():
        pipe.set(k, v, ex=CACHE_TTL)
    pipe.execute()
    log(f"valkey: {len(desired)} projection(s) cached, {len(stray)} stray key(s) purged")


# -- S3 audit archive ---------------------------------------------------------
def list_versions(s3, bucket):
    versions, markers = [], []
    kw = {"Bucket": bucket}
    while True:
        r = s3.list_object_versions(**kw)
        versions.extend(r.get("Versions", []) or [])
        markers.extend(r.get("DeleteMarkers", []) or [])
        if not r.get("IsTruncated"):
            break
        kw = {"Bucket": bucket}
        if r.get("NextKeyMarker"):
            kw["KeyMarker"] = r["NextKeyMarker"]
        if r.get("NextVersionIdMarker"):
            kw["VersionIdMarker"] = r["NextVersionIdMarker"]
    # objects in a bucket that was never versioned may not be listed as versions
    if not versions and not markers:
        kw = {"Bucket": bucket}
        while True:
            r = s3.list_objects_v2(**kw)
            for o in r.get("Contents", []) or []:
                versions.append({"Key": o["Key"], "VersionId": "null", "IsLatest": True})
            if not r.get("IsTruncated"):
                break
            kw["ContinuationToken"] = r["NextContinuationToken"]
    return versions, markers


def batch_body(rows):
    return "".join(canonical_envelope(r["payload"]) + "\n" for r in rows).encode("utf-8")


def batch_key(rows, body):
    digest = hashlib.sha256(body).hexdigest()[:16]
    return f"{AUDIT_PREFIX}batch-{rows[0]['seq']:08d}-{rows[-1]['seq']:08d}-{digest}.ndjson"


def delete_versions(s3, bucket, objs):
    objs = list(objs)
    for i in range(0, len(objs), 500):
        chunk = objs[i:i + 500]
        try:
            r = s3.delete_objects(Bucket=bucket, Delete={"Objects": chunk, "Quiet": True})
            for err in r.get("Errors", []) or []:
                log(f"s3 delete error {err}")
                o = {"Key": err["Key"]}
                if err.get("VersionId"):
                    o["VersionId"] = err["VersionId"]
                s3.delete_object(Bucket=bucket, **o)
        except Exception as e:
            log(f"delete_objects failed ({e}); deleting one by one")
            for o in chunk:
                try:
                    s3.delete_object(Bucket=bucket, **o)
                except Exception as e2:
                    log(f"delete_object {o}: {e2}")


def converge_s3(conn, bucket):
    s3 = client("s3")
    rows = load_outbox(conn)
    by_seq = {r["seq"]: r for r in rows}
    seqs = [r["seq"] for r in rows]
    versions, markers = list_versions(s3, bucket)

    latest = {}
    for v in versions:
        if v.get("IsLatest"):
            latest[v["Key"]] = v
    # keys whose latest entry is a delete marker have no current object
    for mk in markers:
        if mk.get("IsLatest"):
            latest.pop(mk["Key"], None)

    import bisect
    candidates = []
    for key, v in latest.items():
        m = BATCH_RE.match(key)
        if not m:
            continue
        first, last, digest = int(m.group(1)), int(m.group(2)), m.group(3)
        if first > last or first not in by_seq or last not in by_seq:
            continue
        lo = bisect.bisect_left(seqs, first)
        hi = bisect.bisect_right(seqs, last)
        slice_rows = [by_seq[s] for s in seqs[lo:hi]]
        if any(r["published_at"] is None for r in slice_rows):
            continue
        try:
            kw = {"Bucket": bucket, "Key": key}
            if v.get("VersionId") and v["VersionId"] != "null":
                kw["VersionId"] = v["VersionId"]
            body = s3.get_object(**kw)["Body"].read()
        except Exception as e:
            log(f"s3 get {key}: {e}")
            continue
        if hashlib.sha256(body).hexdigest()[:16] != digest:
            continue
        if body != batch_body(slice_rows):
            continue
        candidates.append((first, last, key, v.get("VersionId"), slice_rows))

    candidates.sort(key=lambda c: (c[0], c[1]))
    accepted = []
    last_end = -1
    for c in candidates:
        if c[0] > last_end:
            accepted.append(c)
            last_end = c[1]

    keep = {(c[2], c[3]) for c in accepted}
    to_delete = []
    for v in versions:
        if (v["Key"], v.get("VersionId")) not in keep:
            o = {"Key": v["Key"]}
            if v.get("VersionId") and v["VersionId"] != "null":
                o["VersionId"] = v["VersionId"]
            to_delete.append(o)
    for mk in markers:
        o = {"Key": mk["Key"]}
        if mk.get("VersionId"):
            o["VersionId"] = mk["VersionId"]
        to_delete.append(o)

    covered = set()
    for c in accepted:
        for r in c[4]:
            covered.add(r["seq"])

    # build new batches from runs of uncovered, published rows
    runs, cur = [], []
    for s in seqs:
        r = by_seq[s]
        if s in covered or r["published_at"] is None:
            if cur:
                runs.append(cur)
                cur = []
            continue
        cur.append(r)
        if len(cur) >= AUDIT_BATCH:
            runs.append(cur)
            cur = []
    if cur:
        runs.append(cur)

    written = []
    for run in runs:
        body = batch_body(run)
        key = batch_key(run, body)
        s3.put_object(Bucket=bucket, Key=key, Body=body, ContentType="application/x-ndjson")
        written.append(key)
        for r in run:
            covered.add(r["seq"])

    if to_delete:
        delete_versions(s3, bucket, to_delete)

    # purge any noncurrent versions created by overwrites of identical keys
    versions2, markers2 = list_versions(s3, bucket)
    extra = []
    for v in versions2:
        if not v.get("IsLatest"):
            extra.append({"Key": v["Key"], "VersionId": v["VersionId"]})
    for mk in markers2:
        extra.append({"Key": mk["Key"], "VersionId": mk["VersionId"]})
    if extra:
        delete_versions(s3, bucket, extra)

    # stamp archived_at for every archived row
    stamp = sorted(s for s in covered if by_seq[s]["archived_at"] is None)
    if stamp:
        with conn.cursor() as cur:
            cur.execute("""
                UPDATE clearledger.outbox
                   SET archived_at = GREATEST(NOW(), published_at)
                 WHERE seq = ANY(%s) AND archived_at IS NULL AND published_at IS NOT NULL""", (stamp,))
        conn.commit()
    changes = len(written) + len(to_delete) + len(extra) + len(stamp)
    log(f"s3: kept {len(accepted)} batch(es), wrote {len(written)}, purged {len(to_delete) + len(extra)} "
        f"version(s)/marker(s), stamped {len(stamp)} row(s)")
    return changes


def converge():
    m = manifest()
    conn = pg_connect()
    conn.autocommit = False
    queue_url = m["messaging"]["queue_url"]
    publish_outbox(conn, queue_url)
    wait_queue_drained(queue_url, m["messaging"]["event_source_mapping_uuid"])
    bucket = m["audit"]["bucket_name"]
    for i in range(3):
        if converge_s3(conn, bucket) == 0:
            break
    table = m["projections"]["table_name"]
    for i in range(3):
        changed, _ = converge_dynamo(conn, table)
        if changed == 0:
            break
    # a few more relay passes in case live traffic added rows meanwhile
    if publish_outbox(conn, queue_url):
        wait_queue_drained(queue_url, m["messaging"]["event_source_mapping_uuid"], timeout=45)
        converge_s3(conn, bucket)
        converge_dynamo(conn, table)
    converge_valkey(conn, m["cache"]["endpoint"], m["cache"]["port"])
    conn.close()


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "preapply":
        preapply()
    elif cmd == "postapply":
        postapply()
    elif cmd == "converge":
        converge()
    else:
        print("usage: ops.py preapply|postapply|converge", file=sys.stderr)
        sys.exit(2)

#!/usr/bin/env python3
"""Prefix-scoped teardown of ClearLedger resources (pre- and post-terraform-destroy)."""
import os
import sys
import time

import boto3
from botocore.config import Config

PREFIX = os.environ["CL_PREFIX"]
REGION = os.environ.get("CL_REGION", "us-east-1")
ENDPOINT = os.environ["CL_ENDPOINT"]
TAG_KEY = "ClearLedgerDeployment"
CFG = Config(retries={"max_attempts": 6, "mode": "standard"}, connect_timeout=10, read_timeout=60)


def log(msg):
    print(f"[sweep] {msg}", file=sys.stderr, flush=True)


def c(name):
    return boto3.client(name, endpoint_url=ENDPOINT, region_name=REGION,
                        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID", "test"),
                        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY", "test"), config=CFG)


def ours(name):
    if not name:
        return False
    if name.startswith("cl-base"):
        return False
    return name == PREFIX or name.startswith(PREFIX + "-") or name.startswith(PREFIX + "_") \
        or name.startswith(f"/clearledger/{PREFIX}/") or name.startswith(f"alias/{PREFIX}-")


def tagged(tags):
    if isinstance(tags, dict):
        return tags.get(TAG_KEY) == PREFIX
    for t in tags or []:
        if (t.get("Key") or t.get("key")) == TAG_KEY and (t.get("Value") or t.get("value")) == PREFIX:
            return True
    return False


def safe(fn, *a, **kw):
    try:
        return fn(*a, **kw)
    except Exception as e:  # noqa
        log(f"{getattr(fn, '__name__', fn)}: {str(e)[:200]}")
        return None


def purge_bucket(s3, b):
    kw = {"Bucket": b}
    while True:
        r = safe(s3.list_object_versions, **kw)
        if not r:
            break
        objs = [{"Key": v["Key"], "VersionId": v["VersionId"]} for v in (r.get("Versions") or [])]
        objs += [{"Key": v["Key"], "VersionId": v["VersionId"]} for v in (r.get("DeleteMarkers") or [])]
        for i in range(0, len(objs), 500):
            safe(s3.delete_objects, Bucket=b, Delete={"Objects": objs[i:i + 500], "Quiet": True})
        if not r.get("IsTruncated"):
            break
        kw = {"Bucket": b, "KeyMarker": r.get("NextKeyMarker"), "VersionIdMarker": r.get("NextVersionIdMarker")}
        kw = {k: v for k, v in kw.items() if v}
    r = safe(s3.list_objects_v2, Bucket=b)
    for o in (r or {}).get("Contents", []) or []:
        safe(s3.delete_object, Bucket=b, Key=o["Key"])


def buckets(delete):
    s3 = c("s3")
    for b in (safe(s3.list_buckets) or {}).get("Buckets", []):
        name = b["Name"]
        mine = ours(name)
        if not mine and not name.startswith("cl-base"):
            t = safe(s3.get_bucket_tagging, Bucket=name) if False else None
            try:
                t = s3.get_bucket_tagging(Bucket=name).get("TagSet", [])
                mine = tagged(t)
            except Exception:
                pass
        if not mine:
            continue
        log(f"purging bucket {name}")
        purge_bucket(s3, name)
        if delete:
            safe(s3.delete_bucket, Bucket=name)


def iam_roles(delete):
    iam = c("iam")
    roles = []
    for p in iam.get_paginator("list_roles").paginate():
        roles.extend(p.get("Roles", []))
    for r in roles:
        name = r["RoleName"]
        if not ours(name):
            continue
        for p in (safe(iam.list_role_policies, RoleName=name) or {}).get("PolicyNames", []):
            safe(iam.delete_role_policy, RoleName=name, PolicyName=p)
        for p in (safe(iam.list_attached_role_policies, RoleName=name) or {}).get("AttachedPolicies", []):
            safe(iam.detach_role_policy, RoleName=name, PolicyArn=p["PolicyArn"])
        if r.get("PermissionsBoundary"):
            safe(iam.delete_role_permissions_boundary, RoleName=name)
        for ip in (safe(iam.list_instance_profiles_for_role, RoleName=name) or {}).get("InstanceProfiles", []):
            safe(iam.remove_role_from_instance_profile, InstanceProfileName=ip["InstanceProfileName"], RoleName=name)
        if delete:
            log(f"deleting role {name}")
            safe(iam.delete_role, RoleName=name)
    if delete:
        for p in (safe(iam.list_instance_profiles) or {}).get("InstanceProfiles", []):
            if ours(p["InstanceProfileName"]):
                safe(iam.delete_instance_profile, InstanceProfileName=p["InstanceProfileName"])
    pols = []
    for p in iam.get_paginator("list_policies").paginate(Scope="Local"):
        pols.extend(p.get("Policies", []))
    for p in pols:
        if not ours(p["PolicyName"]):
            continue
        arn = p["Arn"]
        ents = safe(iam.list_entities_for_policy, PolicyArn=arn) or {}
        for r in ents.get("PolicyRoles", []):
            safe(iam.detach_role_policy, RoleName=r["RoleName"], PolicyArn=arn)
        for u in ents.get("PolicyUsers", []):
            safe(iam.detach_user_policy, UserName=u["UserName"], PolicyArn=arn)
        for g in ents.get("PolicyGroups", []):
            safe(iam.detach_group_policy, GroupName=g["GroupName"], PolicyArn=arn)
        if delete:
            for v in (safe(iam.list_policy_versions, PolicyArn=arn) or {}).get("Versions", []):
                if not v.get("IsDefaultVersion"):
                    safe(iam.delete_policy_version, PolicyArn=arn, VersionId=v["VersionId"])
            log(f"deleting policy {arn}")
            safe(iam.delete_policy, PolicyArn=arn)


def pre():
    buckets(delete=False)
    iam_roles(delete=False)
    # stop ESMs / schedules early so nothing writes during teardown
    lam = c("lambda")
    for m in (safe(lam.list_event_source_mappings) or {}).get("EventSourceMappings", []):
        fn = m.get("FunctionArn", "").split(":")[-1]
        if ours(fn) or PREFIX in m.get("EventSourceArn", ""):
            safe(lam.delete_event_source_mapping, UUID=m["UUID"])


def post():
    lam = c("lambda")
    for m in (safe(lam.list_event_source_mappings) or {}).get("EventSourceMappings", []):
        fn = m.get("FunctionArn", "").split(":")[-1]
        if ours(fn) or (":" + PREFIX + "-") in m.get("EventSourceArn", ""):
            log(f"deleting esm {m['UUID']}")
            safe(lam.delete_event_source_mapping, UUID=m["UUID"])
    fns = []
    for p in lam.get_paginator("list_functions").paginate():
        fns.extend(p.get("Functions", []))
    for f in fns:
        if ours(f["FunctionName"]):
            log(f"deleting lambda {f['FunctionName']}")
            safe(lam.delete_function, FunctionName=f["FunctionName"])

    sch = c("scheduler")
    for g in (safe(sch.list_schedule_groups) or {}).get("ScheduleGroups", []):
        gname = g["Name"]
        for s in (safe(sch.list_schedules, GroupName=gname) or {}).get("Schedules", []):
            if ours(s["Name"]):
                log(f"deleting schedule {s['Name']}")
                safe(sch.delete_schedule, Name=s["Name"], GroupName=gname)
        if gname != "default" and ours(gname):
            safe(sch.delete_schedule_group, Name=gname)

    ev = c("events")
    for r in (safe(ev.list_rules) or {}).get("Rules", []):
        if ours(r["Name"]):
            tg = (safe(ev.list_targets_by_rule, Rule=r["Name"]) or {}).get("Targets", [])
            if tg:
                safe(ev.remove_targets, Rule=r["Name"], Ids=[t["Id"] for t in tg], Force=True)
            safe(ev.delete_rule, Name=r["Name"], Force=True)

    sqs = c("sqs")
    for q in (safe(sqs.list_queues, QueueNamePrefix=PREFIX) or {}).get("QueueUrls", []) or []:
        if ours(q.rsplit("/", 1)[-1]):
            log(f"deleting queue {q}")
            safe(sqs.delete_queue, QueueUrl=q)

    ddb = c("dynamodb")
    for t in (safe(ddb.list_tables) or {}).get("TableNames", []):
        if ours(t):
            log(f"deleting table {t}")
            safe(ddb.delete_table, TableName=t)

    logs = c("logs")
    for prefix in (f"/clearledger/{PREFIX}", PREFIX, f"/aws/lambda/{PREFIX}", f"/ecs/{PREFIX}"):
        for g in (safe(logs.describe_log_groups, logGroupNamePrefix=prefix) or {}).get("logGroups", []):
            n = g["logGroupName"]
            if ours(n) or n.startswith(f"/aws/lambda/{PREFIX}-") or n.startswith(f"/ecs/{PREFIX}"):
                log(f"deleting log group {n}")
                safe(logs.delete_log_group, logGroupName=n)

    ecs = c("ecs")
    for arn in (safe(ecs.list_clusters) or {}).get("clusterArns", []):
        name = arn.rsplit("/", 1)[-1]
        if not ours(name):
            continue
        for s in (safe(ecs.list_services, cluster=arn) or {}).get("serviceArns", []):
            safe(ecs.update_service, cluster=arn, service=s, desiredCount=0)
            safe(ecs.delete_service, cluster=arn, service=s, force=True)
        for t in (safe(ecs.list_tasks, cluster=arn) or {}).get("taskArns", []):
            safe(ecs.stop_task, cluster=arn, task=t)
        log(f"deleting ecs cluster {name}")
        safe(ecs.delete_cluster, cluster=arn)
    for fam in (safe(ecs.list_task_definition_families, familyPrefix=PREFIX, status="ACTIVE") or {}).get("families", []):
        if ours(fam):
            for td in (safe(ecs.list_task_definitions, familyPrefix=fam) or {}).get("taskDefinitionArns", []):
                safe(ecs.deregister_task_definition, taskDefinition=td)

    elb = c("elbv2")
    for lb in (safe(elb.describe_load_balancers) or {}).get("LoadBalancers", []):
        if ours(lb["LoadBalancerName"]):
            for l in (safe(elb.describe_listeners, LoadBalancerArn=lb["LoadBalancerArn"]) or {}).get("Listeners", []):
                safe(elb.delete_listener, ListenerArn=l["ListenerArn"])
            log(f"deleting alb {lb['LoadBalancerName']}")
            safe(elb.delete_load_balancer, LoadBalancerArn=lb["LoadBalancerArn"])
    for tg in (safe(elb.describe_target_groups) or {}).get("TargetGroups", []):
        if ours(tg["TargetGroupName"]):
            safe(elb.delete_target_group, TargetGroupArn=tg["TargetGroupArn"])

    rds = c("rds")
    for db in (safe(rds.describe_db_instances) or {}).get("DBInstances", []):
        if ours(db["DBInstanceIdentifier"]):
            log(f"deleting rds {db['DBInstanceIdentifier']}")
            safe(rds.delete_db_instance, DBInstanceIdentifier=db["DBInstanceIdentifier"],
                 SkipFinalSnapshot=True, DeleteAutomatedBackups=True)
    for sn in (safe(rds.describe_db_snapshots) or {}).get("DBSnapshots", []):
        if ours(sn.get("DBSnapshotIdentifier")) or ours(sn.get("DBInstanceIdentifier")):
            safe(rds.delete_db_snapshot, DBSnapshotIdentifier=sn["DBSnapshotIdentifier"])

    ec = c("elasticache")
    for rg in (safe(ec.describe_replication_groups) or {}).get("ReplicationGroups", []):
        if ours(rg["ReplicationGroupId"]):
            log(f"deleting replication group {rg['ReplicationGroupId']}")
            safe(ec.delete_replication_group, ReplicationGroupId=rg["ReplicationGroupId"])
    for cc in (safe(ec.describe_cache_clusters) or {}).get("CacheClusters", []):
        if ours(cc["CacheClusterId"]) and not cc.get("ReplicationGroupId"):
            safe(ec.delete_cache_cluster, CacheClusterId=cc["CacheClusterId"])

    cog = c("cognito-idp")
    for up in (safe(cog.list_user_pools, MaxResults=60) or {}).get("UserPools", []):
        if ours(up["Name"]):
            d = (safe(cog.describe_user_pool, UserPoolId=up["Id"]) or {}).get("UserPool", {})
            if d.get("Domain"):
                safe(cog.delete_user_pool_domain, Domain=d["Domain"], UserPoolId=up["Id"])
            log(f"deleting user pool {up['Name']}")
            safe(cog.delete_user_pool, UserPoolId=up["Id"])

    sm = c("secretsmanager")
    for s in (safe(sm.list_secrets) or {}).get("SecretList", []):
        if ours(s["Name"]) or tagged(s.get("Tags")):
            safe(sm.delete_secret, SecretId=s["ARN"], ForceDeleteWithoutRecovery=True)
    ssm = c("ssm")
    for p in (safe(ssm.describe_parameters) or {}).get("Parameters", []):
        if ours(p["Name"]) or p["Name"].startswith(f"/{PREFIX}/") or p["Name"].startswith(f"/clearledger/{PREFIX}/"):
            safe(ssm.delete_parameter, Name=p["Name"])

    buckets(delete=True)
    iam_roles(delete=True)

    # wait for data stores that block subnet/SG deletion
    for _ in range(60):
        busy = [d for d in (safe(rds.describe_db_instances) or {}).get("DBInstances", []) if ours(d["DBInstanceIdentifier"])]
        busy += [r for r in (safe(ec.describe_replication_groups) or {}).get("ReplicationGroups", []) if ours(r["ReplicationGroupId"])]
        if not busy:
            break
        time.sleep(3)
    for g in (safe(rds.describe_db_subnet_groups) or {}).get("DBSubnetGroups", []):
        if ours(g["DBSubnetGroupName"]):
            safe(rds.delete_db_subnet_group, DBSubnetGroupName=g["DBSubnetGroupName"])
    for g in (safe(ec.describe_cache_subnet_groups) or {}).get("CacheSubnetGroups", []):
        if ours(g["CacheSubnetGroupName"]):
            safe(ec.delete_cache_subnet_group, CacheSubnetGroupName=g["CacheSubnetGroupName"])

    kms = c("kms")
    keys = set()
    for a in (safe(kms.list_aliases) or {}).get("Aliases", []):
        if ours(a["AliasName"]):
            if a.get("TargetKeyId"):
                keys.add(a["TargetKeyId"])
            safe(kms.delete_alias, AliasName=a["AliasName"])
    for k in (safe(kms.list_keys) or {}).get("Keys", []):
        tags = (safe(kms.list_resource_tags, KeyId=k["KeyId"]) or {}).get("Tags", [])
        if any(t.get("TagKey") == TAG_KEY and t.get("TagValue") == PREFIX for t in tags):
            keys.add(k["KeyId"])
    for k in keys:
        meta = (safe(kms.describe_key, KeyId=k) or {}).get("KeyMetadata", {})
        if meta.get("KeyManager") == "AWS":
            continue
        if meta.get("KeyState") not in ("PendingDeletion", None):
            log(f"scheduling deletion of kms key {k}")
            safe(kms.schedule_key_deletion, KeyId=k, PendingWindowInDays=7)

    ec2 = c("ec2")
    flt = [{"Name": f"tag:{TAG_KEY}", "Values": [PREFIX]}]
    vpcs = {v["VpcId"] for v in (safe(ec2.describe_vpcs, Filters=flt) or {}).get("Vpcs", [])}
    for v in (safe(ec2.describe_vpcs) or {}).get("Vpcs", []):
        name = next((t["Value"] for t in v.get("Tags", []) or [] if t["Key"] == "Name"), "")
        if ours(name):
            vpcs.add(v["VpcId"])
    for vpc in vpcs:
        vf = [{"Name": "vpc-id", "Values": [vpc]}]
        for e in (safe(ec2.describe_vpc_endpoints, Filters=vf) or {}).get("VpcEndpoints", []):
            safe(ec2.delete_vpc_endpoints, VpcEndpointIds=[e["VpcEndpointId"]])
        for n in (safe(ec2.describe_nat_gateways, Filters=vf) or {}).get("NatGateways", []):
            safe(ec2.delete_nat_gateway, NatGatewayId=n["NatGatewayId"])
        for eni in (safe(ec2.describe_network_interfaces, Filters=vf) or {}).get("NetworkInterfaces", []):
            if eni.get("Attachment"):
                safe(ec2.detach_network_interface, AttachmentId=eni["Attachment"]["AttachmentId"], Force=True)
            safe(ec2.delete_network_interface, NetworkInterfaceId=eni["NetworkInterfaceId"])
        sgs = [g for g in (safe(ec2.describe_security_groups, Filters=vf) or {}).get("SecurityGroups", [])
               if g["GroupName"] != "default"]
        for g in sgs:
            if g.get("IpPermissions"):
                safe(ec2.revoke_security_group_ingress, GroupId=g["GroupId"], IpPermissions=g["IpPermissions"])
            if g.get("IpPermissionsEgress"):
                safe(ec2.revoke_security_group_egress, GroupId=g["GroupId"], IpPermissions=g["IpPermissionsEgress"])
        for g in sgs:
            safe(ec2.delete_security_group, GroupId=g["GroupId"])
        for igw in (safe(ec2.describe_internet_gateways, Filters=[{"Name": "attachment.vpc-id", "Values": [vpc]}]) or {}).get("InternetGateways", []):
            safe(ec2.detach_internet_gateway, InternetGatewayId=igw["InternetGatewayId"], VpcId=vpc)
            safe(ec2.delete_internet_gateway, InternetGatewayId=igw["InternetGatewayId"])
        for sn in (safe(ec2.describe_subnets, Filters=vf) or {}).get("Subnets", []):
            safe(ec2.delete_subnet, SubnetId=sn["SubnetId"])
        for rt in (safe(ec2.describe_route_tables, Filters=vf) or {}).get("RouteTables", []):
            if any(a.get("Main") for a in rt.get("Associations", [])):
                continue
            for a in rt.get("Associations", []):
                safe(ec2.disassociate_route_table, AssociationId=a["RouteTableAssociationId"])
            safe(ec2.delete_route_table, RouteTableId=rt["RouteTableId"])
        log(f"deleting vpc {vpc}")
        safe(ec2.delete_vpc, VpcId=vpc)
    # stray tagged items outside our VPC
    for igw in (safe(ec2.describe_internet_gateways, Filters=flt) or {}).get("InternetGateways", []):
        for a in igw.get("Attachments", []):
            safe(ec2.detach_internet_gateway, InternetGatewayId=igw["InternetGatewayId"], VpcId=a["VpcId"])
        safe(ec2.delete_internet_gateway, InternetGatewayId=igw["InternetGatewayId"])
    for g in (safe(ec2.describe_security_groups, Filters=flt) or {}).get("SecurityGroups", []):
        if g["GroupName"] != "default":
            safe(ec2.delete_security_group, GroupId=g["GroupId"])
    for a in (safe(ec2.describe_addresses, Filters=flt) or {}).get("Addresses", []):
        safe(ec2.release_address, AllocationId=a["AllocationId"])


if __name__ == "__main__":
    {"pre": pre, "post": post}[sys.argv[1]]()
